"use client";

import React, { useEffect, useState, useRef } from "react";
import { motion, useReducedMotion } from "framer-motion";
import {
  Home,
  Layers,
  Compass,
  Sparkles,
  ArrowRight,
} from "lucide-react";
import { cn } from "@/lib/utils";

export interface FloatingNavItemData {
  id?: string;
  label: string;
  href?: string;
  icon?: React.ComponentType<{ className?: string }>;
  active?: boolean;
  onClick?: () => void;
  badge?: string | number;
}

export interface FloatingNavProps {
  /** Array of navigation links or items to render */
  items?: FloatingNavItemData[];
  /** Brand element or logo rendered on the left */
  logo?: React.ReactNode;
  /** Actions or call-to-action buttons on the right */
  actions?: React.ReactNode;
  /** Custom children or function child receiving current shrunk state */
  children?:
    | React.ReactNode
    | ((props: { isShrunk: boolean }) => React.ReactNode);
  /** Floating distance in pixels from the top edge. Default: 5 */
  topOffset?: number | string;
  /** Vertical scroll threshold in pixels before shrinking is triggered. Default: 40 */
  scrollThreshold?: number;
  /** Scroll delta sensitivity threshold. Default: 4 */
  scrollTolerance?: number;
  /** Custom scroll container ref to track instead of window */
  scrollContainerRef?: React.RefObject<HTMLElement | null>;
  /** Controlled shrink state */
  isShrunk?: boolean;
  /** Callback triggered when shrink state changes */
  onShrinkChange?: (shrunk: boolean) => void;
  /** Max-width Tailwind class when expanded. Default: "w-full max-w-6xl" */
  expandedWidth?: string;
  /** Max-width Tailwind class when shrunk. Default: "w-full max-w-xl sm:max-w-2xl" */
  shrunkWidth?: string;
  /** CSS positioning style. Default: "sticky" */
  position?: "sticky" | "fixed";
  /** Framer motion spring stiffness. Default: 260 */
  stiffness?: number;
  /** Framer motion spring damping. Default: 26 */
  damping?: number;
  /** Framer motion spring mass. Default: 0.85 */
  mass?: number;
  /** Additional className for the inner animated floating nav */
  className?: string;
  /** Additional className for the outer container wrapper */
  containerClassName?: string;
  /** Show animated active indicator pill. Default: true */
  showActiveIndicator?: boolean;
}

const DEFAULT_ITEMS: FloatingNavItemData[] = [
  { id: "home", label: "Home", href: "#", icon: Home },
  { id: "components", label: "Components", href: "#components", icon: Layers, active: true },
  { id: "blocks", label: "Blocks", href: "#blocks", icon: Compass },
  { id: "showcase", label: "Showcase", href: "#showcase", icon: Sparkles },
];

function DefaultBrandLogo({ isShrunk }: { isShrunk: boolean }) {
  return (
    <div className="flex items-center gap-2 select-none">
      <div className="relative flex h-7 w-7 items-center justify-center rounded-lg bg-neutral-950 text-white dark:bg-white dark:text-neutral-950 shadow-xs">
        <span className="font-mono text-xs font-bold">B</span>
        <span className="absolute -top-0.5 -right-0.5 flex h-2 w-2">
          <span className="absolute inline-flex h-full w-full animate-ping rounded-full bg-blue-400 opacity-75" />
          <span className="relative inline-flex h-2 w-2 rounded-full bg-blue-500" />
        </span>
      </div>
      <span
        className={cn(
          "font-semibold text-sm tracking-tight text-neutral-900 dark:text-white transition-opacity duration-200",
          isShrunk && "hidden sm:inline"
        )}
      >
        BoseUI
      </span>
    </div>
  );
}

function DefaultCtaAction({ isShrunk }: { isShrunk: boolean }) {
  return (
    <button
      type="button"
      className={cn(
        "group relative inline-flex items-center justify-center gap-1.5 rounded-full font-medium transition-all duration-200",
        "bg-neutral-950 text-white hover:bg-neutral-800 dark:bg-white dark:text-neutral-950 dark:hover:bg-neutral-200",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-neutral-400 dark:focus-visible:ring-neutral-600",
        isShrunk ? "h-8 px-3 text-xs" : "h-9 px-4 text-xs sm:text-sm shadow-xs"
      )}
    >
      <span>Get Started</span>
      <ArrowRight className="h-3.5 w-3.5 transition-transform duration-200 group-hover:translate-x-0.5" />
    </button>
  );
}

export function FloatingNav({
  items = DEFAULT_ITEMS,
  logo,
  actions,
  children,
  topOffset = 5,
  scrollThreshold = 40,
  scrollTolerance = 4,
  scrollContainerRef,
  isShrunk: controlledShrunk,
  onShrinkChange,
  expandedWidth = "w-full max-w-6xl",
  shrunkWidth = "w-full max-w-xl sm:max-w-2xl",
  position = "sticky",
  stiffness = 260,
  damping = 26,
  mass = 0.85,
  className,
  containerClassName,
  showActiveIndicator = true,
}: FloatingNavProps) {
  const [internalShrunk, setInternalShrunk] = useState(false);
  const isShrunk = controlledShrunk !== undefined ? controlledShrunk : internalShrunk;

  const initialActive = items.find((i) => i.active)?.id ?? items[0]?.id ?? items[0]?.label;
  const [activeId, setActiveId] = useState<string | undefined>(initialActive);
  const shouldReduceMotion = useReducedMotion();

  // Scroll detection engine: Shrinks when scrolling down, expands on scroll-up or top
  useEffect(() => {
    const getTarget = () =>
      scrollContainerRef?.current ??
      (typeof window !== "undefined" ? window : null);

    const getScrollY = (target: Window | HTMLElement) => {
      if ("scrollY" in target) {
        return target.scrollY;
      }
      return target.scrollTop;
    };

    const target = getTarget();
    if (!target) return;

    let lastScrollY = getScrollY(target);
    let ticking = false;

    const handleScroll = () => {
      if (!ticking) {
        window.requestAnimationFrame(() => {
          const currentTarget = getTarget();
          if (!currentTarget) {
            ticking = false;
            return;
          }
          const currentScrollY = getScrollY(currentTarget);
          const diff = currentScrollY - lastScrollY;

          // Expand when at or near the very top
          if (currentScrollY <= scrollThreshold) {
            if (internalShrunk) {
              setInternalShrunk(false);
              onShrinkChange?.(false);
            }
          }
          // Shrink when scrolling down past threshold
          else if (diff > scrollTolerance && currentScrollY > scrollThreshold) {
            if (!internalShrunk) {
              setInternalShrunk(true);
              onShrinkChange?.(true);
            }
          }
          // Expand when scrolling up
          else if (diff < -scrollTolerance) {
            if (internalShrunk) {
              setInternalShrunk(false);
              onShrinkChange?.(false);
            }
          }

          lastScrollY = currentScrollY;
          ticking = false;
        });
        ticking = true;
      }
    };

    target.addEventListener("scroll", handleScroll as EventListener, {
      passive: true,
    });

    return () => {
      target.removeEventListener("scroll", handleScroll as EventListener);
    };
  }, [
    scrollContainerRef,
    scrollThreshold,
    scrollTolerance,
    internalShrunk,
    onShrinkChange,
  ]);

  const springTransition = shouldReduceMotion
    ? { duration: 0 }
    : {
        type: "spring",
        stiffness,
        damping,
        mass,
      };

  return (
    <header
      className={cn(
        position === "fixed" ? "fixed left-0 right-0" : "sticky",
        "z-50 w-full px-3 sm:px-6 pointer-events-none transition-all duration-300",
        containerClassName
      )}
      style={{
        top: typeof topOffset === "number" ? `${topOffset}px` : topOffset,
      }}
    >
      <motion.nav
        layout={!shouldReduceMotion}
        transition={springTransition}
        role="navigation"
        aria-label="Floating navigation"
        className={cn(
          "pointer-events-auto mx-auto flex items-center justify-between",
          "border backdrop-blur-xl transition-colors duration-300",
          "bg-white/85 dark:bg-[#0A0A0A]/85 border-neutral-200/80 dark:border-neutral-800/80",
          isShrunk
            ? cn(
                "h-12 rounded-full shadow-lg shadow-black/10 dark:shadow-black/40 px-3 sm:px-4",
                shrunkWidth
              )
            : cn(
                "h-14 sm:h-16 rounded-2xl shadow-xs px-4 sm:px-6",
                expandedWidth
              ),
          className
        )}
      >
        {typeof children === "function" ? (
          children({ isShrunk })
        ) : children ? (
          children
        ) : (
          <>
            {/* Left Brand Slot */}
            <div className="flex items-center shrink-0">
              {logo !== undefined ? (
                logo
              ) : (
                <DefaultBrandLogo isShrunk={isShrunk} />
              )}
            </div>

            {/* Center Navigation Links */}
            <div className="flex items-center justify-center flex-1 mx-2 sm:mx-4">
              <div className="flex items-center gap-1 sm:gap-1.5">
                {items.map((item, idx) => {
                  const itemId = item.id ?? item.label ?? String(idx);
                  const isItemActive = activeId === itemId;
                  const Icon = item.icon;

                  return (
                    <a
                      key={itemId}
                      href={item.href ?? "#"}
                      onClick={(e) => {
                        if (item.onClick) {
                          e.preventDefault();
                          item.onClick();
                        }
                        setActiveId(itemId);
                      }}
                      className={cn(
                        "relative flex items-center gap-1.5 rounded-full transition-colors duration-200",
                        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500",
                        isShrunk
                          ? "px-2.5 py-1 text-xs"
                          : "px-3 py-1.5 sm:px-3.5 sm:py-2 text-xs sm:text-sm",
                        isItemActive
                          ? "font-medium text-neutral-950 dark:text-white"
                          : "text-neutral-600 hover:text-neutral-950 dark:text-neutral-400 dark:hover:text-white"
                      )}
                    >
                      {isItemActive && showActiveIndicator && (
                        <motion.div
                          layoutId="floatingNavActivePill"
                          transition={springTransition}
                          className="absolute inset-0 rounded-full bg-neutral-100 dark:bg-neutral-800/80 -z-10"
                        />
                      )}
                      {Icon && (
                        <Icon
                          className={cn(
                            "shrink-0",
                            isShrunk ? "h-3.5 w-3.5" : "h-4 w-4"
                          )}
                        />
                      )}
                      <span
                        className={cn(
                          isShrunk ? "hidden sm:inline" : "inline"
                        )}
                      >
                        {item.label}
                      </span>
                      {item.badge && (
                        <span className="ml-0.5 rounded-full bg-blue-500/10 px-1.5 py-0.5 text-[10px] font-semibold text-blue-600 dark:bg-blue-400/15 dark:text-blue-300">
                          {item.badge}
                        </span>
                      )}
                    </a>
                  );
                })}
              </div>
            </div>

            {/* Right Action / CTA Slot */}
            <div className="flex items-center shrink-0">
              {actions !== undefined ? (
                actions
              ) : (
                <DefaultCtaAction isShrunk={isShrunk} />
              )}
            </div>
          </>
        )}
      </motion.nav>
    </header>
  );
}

export default FloatingNav;

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export async function copyToClipboard(text: string): Promise<boolean> {
  if (typeof window === "undefined") return false;

  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
      return true;
    }

    const textArea = document.createElement("textarea");
    textArea.value = text;
    textArea.style.position = "fixed";
    textArea.style.left = "-999999px";
    textArea.style.top = "-999999px";
    document.body.appendChild(textArea);
    textArea.focus();
    textArea.select();
    const succeeded = document.execCommand("copy");
    textArea.remove();
    return succeeded;
  } catch {
    return false;
  }
}
